package com.stymphikeafktimer;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(StymphikeAfkTimerConfig.GROUP)
public interface StymphikeAfkTimerConfig extends Config
{
	String GROUP = "stymphikeAfkTimer";

	@ConfigSection(
		name = "Dimmer",
		description = "Dimmer overlay settings",
		position = 0
	)
	String dimmerSection = "dimmer";

	@ConfigSection(
		name = "Interface hiding",
		description = "Interfaces left visible while the dimmer is active",
		position = 1
	)
	String interfaceSection = "interface";

	@ConfigSection(
		name = "Baited trees",
		description = "Tree highlighting settings",
		position = 2
	)
	String treeSection = "trees";

	@ConfigSection(
		name = "ETA",
		description = "Countdown display settings",
		position = 3
	)
	String etaSection = "eta";

	@ConfigSection(
		name = "Notifications",
		description = "Alerts when the dimmer disappears",
		position = 4
	)
	String notificationsSection = "notifications";

	@ConfigItem(
		keyName = "toggleHotkey",
		name = "Toggle hotkey",
		description = "Toggles the dimmer and widget hiding on or off.",
		section = dimmerSection,
		position = 0
	)
	default Keybind toggleHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "dimmerColor",
		name = "Dimmer colour",
		description = "Colour used by the dimmer overlay.",
		section = dimmerSection,
		position = 1
	)
	default Color dimmerColor()
	{
		return Color.BLACK;
	}

	@Range(
		min = 0,
		max = 100
	)
	@ConfigItem(
		keyName = "dimmerOpacity",
		name = "Dimmer opacity",
		description = "Opacity percentage of the dimmer overlay.",
		section = dimmerSection,
		position = 2
	)
	default int dimmerOpacity()
	{
		return 80;
	}

	@ConfigItem(
		keyName = "unhideInventory",
		name = "Unhide inventory",
		description = "Keeps the inventory visible while the dimmer is active.",
		section = interfaceSection,
		position = 0
	)
	default boolean unhideInventory()
	{
		return false;
	}

	@ConfigItem(
		keyName = "unhideChatbox",
		name = "Unhide chatbox",
		description = "Keeps the chatbox visible while the dimmer is active.",
		section = interfaceSection,
		position = 1
	)
	default boolean unhideChatbox()
	{
		return false;
	}

	@ConfigItem(
		keyName = "unhideInterfaces",
		name = "Unhide interfaces",
		description = "Keeps all game interfaces visible while dimming the scene.",
		section = interfaceSection,
		position = 2
	)
	default boolean unhideInterfaces()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightBaitedTrees",
		name = "Highlight baited trees",
		description = "Outlines stymphike trees that currently contain bait.",
		section = treeSection,
		position = 0
	)
	default boolean highlightBaitedTrees()
	{
		return true;
	}

	@ConfigItem(
		keyName = "baitedTreeColor",
		name = "Baited tree colour",
		description = "Outline colour for baited stymphike trees.",
		section = treeSection,
		position = 1
	)
	default Color baitedTreeColor()
	{
		return Color.GREEN;
	}

	@Range(
		min = 1,
		max = 10
	)
	@ConfigItem(
		keyName = "baitedTreeOutlineWidth",
		name = "Tree outline width",
		description = "Outline width for baited stymphike trees.",
		section = treeSection,
		position = 2
	)
	default int baitedTreeOutlineWidth()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "showCountdown",
		name = "Show ETA countdown",
		description = "Shows a floating countdown while the dimmer is active.",
		section = etaSection,
		position = 0
	)
	default boolean showCountdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "etaColor",
		name = "ETA colour",
		description = "Text colour for the ETA overlay.",
		section = etaSection,
		position = 1
	)
	default Color etaColor()
	{
		return Color.WHITE;
	}

	@Range(
		min = 10,
		max = 64
	)
	@ConfigItem(
		keyName = "etaFontSize",
		name = "ETA font size",
		description = "Sans serif font size for the ETA overlay.",
		section = etaSection,
		position = 2
	)
	default int etaFontSize()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "undimOnKill",
		name = "Undim on kill",
		description = "Keeps the dimmer active until a 1350 or 891 Hunter XP drop is detected.",
		section = etaSection,
		position = 3
	)
	default boolean undimOnKill()
	{
		return true;
	}

	@Range(
		min = 1,
		max = 300
	)
	@ConfigItem(
		keyName = "countdownSeconds",
		name = "ETA seconds",
		description = "Number of seconds used by the custom countdown timer.",
		section = etaSection,
		position = 4
	)
	default int countdownSeconds()
	{
		return 39;
	}

	@ConfigItem(
		keyName = "showOutOfSpears",
		name = "Show out of spears",
		description = "Shows an on-screen warning when no Hunter's spear or makeshift spear is detected in your inventory.",
		section = etaSection,
		position = 5
	)
	default boolean showOutOfSpears()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyWhenDimmerDisappears",
		name = "Windows notification",
		description = "Sends a RuneLite desktop notification when the dimmer disappears.",
		section = notificationsSection,
		position = 0
	)
	default boolean notifyWhenDimmerDisappears()
	{
		return false;
	}

	@ConfigItem(
		keyName = "soundWhenDimmerDisappears",
		name = "Sound notification",
		description = "Plays a system beep when the dimmer disappears.",
		section = notificationsSection,
		position = 1
	)
	default boolean soundWhenDimmerDisappears()
	{
		return false;
	}
}

package com.stymphikeafktimer;

import com.google.inject.Provides;
import java.awt.Toolkit;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Scene;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.StatChanged;
import net.runelite.api.widgets.ComponentID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.Notifier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "Stymphike AFK Timer",
	description = "Dims the client while hidden, highlights baited stymphike trees, and shows a configurable countdown.",
	tags = {"hunter", "stymphike", "afk", "timer", "overlay", "bait"}
)
public class StymphikeAfkTimerPlugin extends Plugin
{
	static final String TREE_NAME = "Stymphike tree";
	static final Set<Integer> TREE_IDS = Set.of(40782, 40783, 40784, 40785, 40786);
	static final String BAITED_ACTION = "Check";
	static final int HIDDEN_VARBIT = 15444;
	static final int HIDDEN_VARBIT_ALT = 16289;
	static final Set<Integer> STYMPHIKE_NPC_IDS = Set.of(15747);
	static final String STYMPHIKE_NPC = "stymphike";
	static final Set<Integer> KILL_XP_DROPS = Set.of(1350, 891);
	static final Set<Integer> SPEAR_IDS = Set.of(ItemID.HUNTERS_SPEAR, ItemID.MAKESHIFT_SPEAR);

	static final int[] INVENTORY_WIDGETS = {
		ComponentID.INVENTORY_CONTAINER,
		ComponentID.FIXED_VIEWPORT_INVENTORY_CONTAINER,
		ComponentID.RESIZABLE_VIEWPORT_INVENTORY_CONTAINER,
		ComponentID.RESIZABLE_VIEWPORT_INVENTORY_PARENT,
		ComponentID.RESIZABLE_VIEWPORT_BOTTOM_LINE_INVENTORY_CONTAINER,
		ComponentID.RESIZABLE_VIEWPORT_BOTTOM_LINE_INVENTORY_PARENT
	};

	static final int[] CHATBOX_WIDGETS = {
		ComponentID.CHATBOX_PARENT,
		ComponentID.CHATBOX_FRAME,
		ComponentID.RESIZABLE_VIEWPORT_CHATBOX_PARENT,
		ComponentID.RESIZABLE_VIEWPORT_BOTTOM_LINE_CHATBOX_PARENT
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private Notifier notifier;

	@Inject
	private StymphikeAfkTimerConfig config;

	@Inject
	private StymphikeDimmerOverlay dimmerOverlay;

	@Inject
	private StymphikeSceneDimmerOverlay sceneDimmerOverlay;

	@Inject
	private StymphikeEtaOverlay etaOverlay;

	@Inject
	private StymphikeTreeOverlay treeOverlay;

	private final Set<GameObject> trees = new HashSet<>();
	private final Set<WorldPoint> baitedTiles = new HashSet<>();
	private final Set<NPC> stymphikes = new HashSet<>();

	private final HotkeyListener toggleHotkey = new HotkeyListener(() -> config.toggleHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			dimmerEnabled = !dimmerEnabled;
		}
	};

	private boolean hidden;
	private boolean dimmerEnabled = true;
	private boolean killLockedDimmer;
	private boolean killUndimmedUntilStartClears;
	private boolean wasDimmed;
	private int hiddenDroppedTick = -1;
	private long timerStartedMillis = -1;
	private int lastHunterXp = -1;

	@Provides
	StymphikeAfkTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(StymphikeAfkTimerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(dimmerOverlay);
		overlayManager.add(sceneDimmerOverlay);
		overlayManager.add(etaOverlay);
		overlayManager.add(treeOverlay);
		keyManager.registerKeyListener(toggleHotkey);
		clientThread.invokeLater(() ->
		{
			rebuildTrees();
			primeHunterXp();
		});
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(toggleHotkey);
		overlayManager.remove(dimmerOverlay);
		overlayManager.remove(sceneDimmerOverlay);
		overlayManager.remove(etaOverlay);
		overlayManager.remove(treeOverlay);
		trees.clear();
		baitedTiles.clear();
		stymphikes.clear();
		hidden = false;
		killLockedDimmer = false;
		killUndimmedUntilStartClears = false;
		wasDimmed = false;
		hiddenDroppedTick = -1;
		timerStartedMillis = -1;
		lastHunterXp = -1;
		dimmerEnabled = true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			trees.clear();
			baitedTiles.clear();
			stymphikes.clear();
			stopTimer();
		}

		if (event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING)
		{
			setHidden(false);
			trees.clear();
			baitedTiles.clear();
			stymphikes.clear();
			killLockedDimmer = false;
			killUndimmedUntilStartClears = false;
			stopTimer();
			lastHunterXp = -1;
		}

		if (event.getGameState() == GameState.LOGGED_IN)
		{
			rebuildTrees();
			primeHunterXp();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getLocalPlayer() == null)
		{
			setHidden(false);
			return;
		}

		setHidden(client.getVarbitValue(HIDDEN_VARBIT) == 1
			|| client.getVarbitValue(HIDDEN_VARBIT_ALT) == 1);
		refreshBaitedTiles();
		final boolean canStart = canStartDimmer();
		if (!canStart)
		{
			killUndimmedUntilStartClears = false;
		}

		if (config.undimOnKill()
			&& !killLockedDimmer
			&& !killUndimmedUntilStartClears
			&& canStart)
		{
			killLockedDimmer = true;
			startTimer();
		}
		else if (!config.undimOnKill() && dimmerEnabled && canStart)
		{
			startTimer();
		}
		if (killLockedDimmer
			&& !hidden
			&& stymphikes.isEmpty()
			&& client.getTickCount() - hiddenDroppedTick > 1)
		{
			killLockedDimmer = false;
			stopTimer();
		}
		checkDimmerTransition();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.HUNTER)
		{
			return;
		}

		if (lastHunterXp >= 0)
		{
			final int xpDrop = event.getXp() - lastHunterXp;
			if (KILL_XP_DROPS.contains(xpDrop))
			{
				killLockedDimmer = false;
				killUndimmedUntilStartClears = true;
				stopTimer();
				checkDimmerTransition();
			}
		}
		lastHunterXp = event.getXp();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		final GameObject obj = event.getGameObject();
		if (isStymphikeTree(obj))
		{
			trees.add(obj);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		final GameObject obj = event.getGameObject();
		trees.remove(obj);
		baitedTiles.remove(obj.getWorldLocation());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (isStymphikeNpc(event.getNpc()))
		{
			stymphikes.add(event.getNpc());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		stymphikes.remove(event.getNpc());
		if (killLockedDimmer && !hidden && stymphikes.isEmpty())
		{
			killLockedDimmer = false;
			stopTimer();
			checkDimmerTransition();
		}
	}

	boolean shouldDim()
	{
		if (!dimmerEnabled)
		{
			return false;
		}

		if (config.undimOnKill())
		{
			if (killLockedDimmer)
			{
				return hidden || !stymphikes.isEmpty();
			}
			return canStartDimmer() && !killUndimmedUntilStartClears;
		}

		return canStartDimmer();
	}

	boolean shouldShowTimers()
	{
		return shouldDim() && config.showCountdown();
	}

	Set<GameObject> getTrees()
	{
		return trees;
	}

	Set<WorldPoint> getBaitedTiles()
	{
		return baitedTiles;
	}

	long getElapsedHiddenMillis()
	{
		return timerStartedMillis < 0 ? 0 : System.currentTimeMillis() - timerStartedMillis;
	}

	boolean isOutOfSpears()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		if (inventory == null)
		{
			return false;
		}

		for (int spearId : SPEAR_IDS)
		{
			if (inventory.contains(spearId))
			{
				return false;
			}
		}
		return true;
	}

	private void setHidden(boolean value)
	{
		if (hidden == value)
		{
			return;
		}

		hidden = value;
		if (hidden)
		{
			hiddenDroppedTick = -1;
			startTimer();
		}
		else
		{
			hiddenDroppedTick = client.getTickCount();
			if (!config.undimOnKill() || !killLockedDimmer)
			{
				killLockedDimmer = false;
				killUndimmedUntilStartClears = false;
				stopTimer();
			}
		}
	}

	private void refreshBaitedTiles()
	{
		baitedTiles.clear();
		for (GameObject tree : trees)
		{
			if (isTreeBaited(tree))
			{
				baitedTiles.add(tree.getWorldLocation());
			}
		}
	}

	private boolean isTreeBaited(GameObject tree)
	{
		ObjectComposition comp = client.getObjectDefinition(tree.getId());
		if (comp == null)
		{
			return false;
		}
		if (comp.getImpostorIds() != null)
		{
			comp = comp.getImpostor();
			if (comp == null)
			{
				return false;
			}
		}

		final String[] actions = comp.getActions();
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if (BAITED_ACTION.equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isStymphikeTree(GameObject obj)
	{
		if (obj == null)
		{
			return false;
		}
		if (TREE_IDS.contains(obj.getId()))
		{
			return true;
		}

		final ObjectComposition comp = client.getObjectDefinition(obj.getId());
		return comp != null && TREE_NAME.equalsIgnoreCase(comp.getName());
	}

	private boolean isStymphikeNpc(NPC npc)
	{
		if (npc == null)
		{
			return false;
		}
		if (STYMPHIKE_NPC_IDS.contains(npc.getId()))
		{
			return true;
		}

		final String name = npc.getName();
		return name != null && name.toLowerCase().contains(STYMPHIKE_NPC);
	}

	private void rebuildTrees()
	{
		trees.clear();
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final Scene scene = client.getScene();
		final Tile[][][] tiles = scene.getTiles();
		final int z = client.getPlane();
		for (int x = 0; x < Constants.SCENE_SIZE; x++)
		{
			for (int y = 0; y < Constants.SCENE_SIZE; y++)
			{
				final Tile tile = tiles[z][x][y];
				if (tile == null)
				{
					continue;
				}
				for (GameObject gameObject : tile.getGameObjects())
				{
					if (isStymphikeTree(gameObject))
					{
						trees.add(gameObject);
					}
				}
			}
		}
		refreshBaitedTiles();
	}

	private boolean canStartDimmer()
	{
		return hidden && !baitedTiles.isEmpty();
	}

	private void primeHunterXp()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			lastHunterXp = client.getSkillExperience(Skill.HUNTER);
		}
	}

	private void startTimer()
	{
		if (timerStartedMillis < 0)
		{
			timerStartedMillis = System.currentTimeMillis();
		}
	}

	private void stopTimer()
	{
		timerStartedMillis = -1;
	}

	private void checkDimmerTransition()
	{
		final boolean dimmed = shouldDim();
		if (wasDimmed && !dimmed)
		{
			alertDimmerDisappeared();
		}
		wasDimmed = dimmed;
	}

	private void alertDimmerDisappeared()
	{
		if (config.notifyWhenDimmerDisappears())
		{
			notifier.notify("Stymphike dimmer disappeared.");
		}
		if (config.soundWhenDimmerDisappears())
		{
			Toolkit.getDefaultToolkit().beep();
		}
	}
}

package com.stymphikeafktimer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Area;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class StymphikeDimmerOverlay extends Overlay
{
	private final Client client;
	private final StymphikeAfkTimerPlugin plugin;
	private final StymphikeAfkTimerConfig config;

	@Inject
	private StymphikeDimmerOverlay(Client client, StymphikeAfkTimerPlugin plugin, StymphikeAfkTimerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldDim() || config.unhideInterfaces())
		{
			return null;
		}

		final Color base = config.dimmerColor();
		final int alpha = Math.max(0, Math.min(255, config.dimmerOpacity() * 255 / 100));
		graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha));
		graphics.fill(buildDimmerArea());
		return null;
	}

	private Area buildDimmerArea()
	{
		final Area area = new Area(new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight()));
		if (config.unhideInventory())
		{
			subtractWidgets(area, StymphikeAfkTimerPlugin.INVENTORY_WIDGETS);
		}
		if (config.unhideChatbox())
		{
			subtractWidgets(area, StymphikeAfkTimerPlugin.CHATBOX_WIDGETS);
		}
		return area;
	}

	private void subtractWidgets(Area area, int[] componentIds)
	{
		for (int componentId : componentIds)
		{
			final Widget widget = client.getWidget(componentId);
			if (widget == null || widget.isHidden())
			{
				continue;
			}

			final Rectangle bounds = widget.getBounds();
			if (bounds != null && !bounds.isEmpty())
			{
				area.subtract(new Area(bounds));
			}
		}
	}
}

package com.stymphikeafktimer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class StymphikeEtaOverlay extends Overlay
{
	private static final String FONT_NAME = Font.SANS_SERIF;
	private static final int PADDING = 4;

	private final StymphikeAfkTimerPlugin plugin;
	private final StymphikeAfkTimerConfig config;

	@Inject
	private StymphikeEtaOverlay(StymphikeAfkTimerPlugin plugin, StymphikeAfkTimerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(Overlay.PRIORITY_HIGH);
		setMovable(true);
		setSnappable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldShowTimers() && !shouldShowOutOfSpears())
		{
			return null;
		}

		final List<String> lines = buildLines();
		if (lines.isEmpty())
		{
			return null;
		}

		final Font previousFont = graphics.getFont();
		final Color previousColor = graphics.getColor();
		final Font font = new Font(FONT_NAME, Font.BOLD, config.etaFontSize());

		graphics.setFont(font);
		final FontMetrics metrics = graphics.getFontMetrics();
		int width = 0;
		for (String line : lines)
		{
			width = Math.max(width, metrics.stringWidth(line));
		}

		width += PADDING * 2;
		final int lineHeight = metrics.getHeight();
		final int height = lineHeight * lines.size() + PADDING * 2;
		int y = PADDING + metrics.getAscent();

		for (String line : lines)
		{
			final int x = PADDING + (width - PADDING * 2 - metrics.stringWidth(line)) / 2;
			graphics.setColor(new Color(0, 0, 0, 160));
			graphics.drawString(line, x + 2, y + 2);
			graphics.setColor(getLineColor(line));
			graphics.drawString(line, x, y);
			y += lineHeight;
		}

		graphics.setFont(previousFont);
		graphics.setColor(previousColor);
		return new Dimension(width, height);
	}

	private List<String> buildLines()
	{
		final List<String> lines = new ArrayList<>();
		if (plugin.shouldShowTimers())
		{
			lines.add(buildCountdownText());
		}
		if (shouldShowOutOfSpears())
		{
			lines.add("Out of spears");
		}
		return lines;
	}

	private boolean shouldShowOutOfSpears()
	{
		return config.showOutOfSpears() && plugin.shouldDim() && plugin.isOutOfSpears();
	}

	private Color getLineColor(String line)
	{
		return "Out of spears".equals(line) ? Color.RED : config.etaColor();
	}

	private String buildCountdownText()
	{
		final long durationMillis = config.countdownSeconds() * 1000L;
		final long remaining = Math.max(0, durationMillis - plugin.getElapsedHiddenMillis());
		return "ETA: " + formatDuration(remaining);
	}

	private String formatDuration(long millis)
	{
		final long totalSeconds = Math.round(millis / 1000.0);
		final long minutes = totalSeconds / 60;
		final long seconds = totalSeconds % 60;
		return String.format("%d:%02d", minutes, seconds);
	}
}

package com.stymphikeafktimer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class StymphikeSceneDimmerOverlay extends Overlay
{
	private final Client client;
	private final StymphikeAfkTimerPlugin plugin;
	private final StymphikeAfkTimerConfig config;

	@Inject
	private StymphikeSceneDimmerOverlay(Client client, StymphikeAfkTimerPlugin plugin, StymphikeAfkTimerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(Overlay.PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldDim() || !config.unhideInterfaces())
		{
			return null;
		}

		final Color base = config.dimmerColor();
		final int alpha = Math.max(0, Math.min(255, config.dimmerOpacity() * 255 / 100));
		graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha));
		graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		return null;
	}
}

package com.stymphikeafktimer;

import java.awt.Dimension;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class StymphikeTreeOverlay extends Overlay
{
	private final StymphikeAfkTimerPlugin plugin;
	private final StymphikeAfkTimerConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private StymphikeTreeOverlay(
		StymphikeAfkTimerPlugin plugin,
		StymphikeAfkTimerConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(java.awt.Graphics2D graphics)
	{
		if (!config.highlightBaitedTrees())
		{
			return null;
		}

		for (GameObject tree : plugin.getTrees())
		{
			final WorldPoint location = tree.getWorldLocation();
			if (plugin.getBaitedTiles().contains(location))
			{
				modelOutlineRenderer.drawOutline(
					tree,
					config.baitedTreeOutlineWidth(),
					config.baitedTreeColor(),
					4);
			}
		}
		return null;
	}
}

